/**
 * Morphing Chromatic Grid
 * Created for OpenProcessing "Patterns" Curation
 */

let myShader; // Variable to hold the shader object

// Vertex shader source code
const vert = `
	precision highp float; // Set high precision for floats
	attribute vec3 aPosition; // Get vertex position from p5
	void main() {
		gl_Position = vec4(aPosition, 1.0); // Pass position directly to clip space
	}
`;

// Fragment shader source code
const frag = `
	precision highp float; // Set high precision for floats
	uniform vec2 u_resolution; // Get canvas dimensions
	uniform float u_time; // Get elapsed time

	// Function to rotate 2D space
	mat2 rotate2d(float _angle){
		return mat2(cos(_angle), -sin(_angle), sin(_angle), cos(_angle)); // Standard rotation matrix
	}

	// Pseudo-random function based on coordinates
	float hash(vec2 p) {
		return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); // Generate random float
	}

	void main() {
		vec2 uv = (gl_FragCoord.xy * 2.0 - u_resolution.xy) / min(u_resolution.y, u_resolution.x); // Normalize UV coordinates

		vec3 color = vec3(0.0); // Initialize background color as black

		vec2 shift = vec2(0.0); // Variable for large-scale movement
		float t = u_time * 0.15; // Slow down global movement for a calm effect
		shift.x = sin(uv.y * 1.5 + t) * 0.3; // Calculate horizontal drift
		shift.y = cos(uv.x * 1.5 + t) * 0.3; // Calculate vertical drift
		uv += shift; // Apply drift to coordinates

		float gridCount = 8.0; // Define number of grid cells
		vec2 gv = fract(uv * gridCount) - 0.5; // Create repeating grid coordinates
		vec2 id = floor(uv * gridCount); // Identify each cell by its ID

		float n = hash(id); // Assign a unique random value to each cell

		gv *= rotate2d(u_time * 0.3 + n * 6.28); // Rotate each cell slowly with a random offset

		// Define the three base colors
		vec3 red    = vec3(0.9, 0.2, 0.2); // Soft red
		vec3 yellow = vec3(0.9, 0.8, 0.1); // Soft yellow
		vec3 green  = vec3(0.1, 0.7, 0.3); // Soft green

		// Calculate a slow, unique color cycle for each cell
		float speed = 0.2 + n * 0.3; // Individual speed variation
		float phase = fract(u_time * speed + n * 5.0); // 0.0 to 1.0 color cycle

		vec3 patternCol; // Variable to store the transitioned color
		// Smoothly interpolate (mix) between the three colors based on the cycle phase
		if(phase < 0.33) {
			patternCol = mix(red, yellow, phase * 3.0); // Transition from red to yellow
		} else if(phase < 0.66) {
			patternCol = mix(yellow, green, (phase - 0.33) * 3.0); // Transition from yellow to green
		} else {
			patternCol = mix(green, red, (phase - 0.66) * 3.0); // Transition from green back to red
		}

		float stripe = smoothstep(-0.1, 0.1, sin(gv.x * 12.0 + u_time * 0.8)); // Create soft-edged stripes

		float dist = length(gv); // Calculate distance from cell center
		float mask = smoothstep(0.42, 0.38, dist); // Create a circular mask

		float finalPattern = stripe * mask; // Combine stripes and circular mask
		color = mix(color, patternCol, finalPattern); // Apply the transitioning color to the pattern

		float dots = smoothstep(0.12, 0.05, length(gv)); // Create a small central glow dot
		color += dots * patternCol * 0.5; // Add subtle glow matching the current color

		gl_FragColor = vec4(color, 1.0); // Output final color to the pixel
	}
`;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL); // Initialize WEBGL canvas
	myShader = createShader(vert, frag); // Compile vertex and fragment shaders
	noStroke(); // Disable outlines for geometry
}

function draw() {
	shader(myShader); // Enable the custom shader
	myShader.setUniform('u_resolution', [width, height]); // Pass canvas size to shader
	myShader.setUniform('u_time', millis() / 1000.0); // Pass elapsed time in seconds to shader

	quad(-1, -1, 1, -1, 1, 1, -1, 1); // Draw full-screen quad to display the shader
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight); // Adjust canvas size on window resize
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
